import "@mantine/core/styles.css"
import "@mantine/charts/styles.css"
import "mantine-contextmenu/styles.css"
import "@mantine/notifications/styles.css"
import 'mantine-datatable/styles.layer.css'
import { MantineProvider } from "@mantine/core"
import theme from "./theme"
import Shell from "@components/Shell/Shell"
import { BrowserRouter, Route, Routes, useParams, useLocation, useNavigate, generatePath } from "react-router"
import ProfilePage from "./pages/ProfilePage"
import HomePage from "./pages/HomePage"
import ErrorPage from "./pages/ErrorPage"
import { SettingsProvider } from "./components/SettingsProvider"
import SettingsPage from "./pages/SettingsPage"
import LeaderboardsPage from "./pages/LeaderboardsPage"
import LeaderboardDetailPage from "./pages/LeaderboardDetailPage"
import RenderErrorBoundary from "@components/RenderErrorBoundary/RenderErrorBoundary"
import { ContextMenuProvider } from "mantine-contextmenu"
import { Notifications } from "@mantine/notifications"
import { BackendProvider } from "./components/BackendProvider"
import { useEffect } from "react"
import BuildsPage from "./pages/BuildsPage"
import AuthCallback from "./pages/auth/AuthCallback"
import { AuthProvider } from "./components/AuthProvider"
import KitchenSinkPage from "./pages/KitchenSinkPage"
import { PrivacyPage } from "@pages/PrivacyPage.tsx"
import AssaultLeaderboardsPage from "./pages/AssaultLeaderboardsPage";
import AssaultLeaderboardsDetailsPage from "./pages/AssaultLeaderboardsDetailsPage";

const ProfilePageWrapper = () => {
    const { uid } = useParams()
    return <ProfilePage key={uid} />
}

const Redirect = ({ to, replace = true }: { to: string, replace?: boolean }) => {
    const navigate = useNavigate()
    const location = useLocation()
    const params = useParams()

    useEffect(() => {
        // preserve search and hash
        const pathname = generatePath(to, params)
        const search = location.search
        const hash = location.hash

        navigate({
            pathname: pathname,
            search,
            hash,
        },{ replace })
    }, [to, replace, navigate, location.search, location.hash, params])

    return null
}

export default function App() {
    return (
        <MantineProvider theme={theme} defaultColorScheme="dark" 
            withStaticClasses withCssVariables withGlobalClasses>
                <Notifications />
                <ContextMenuProvider shadow="md" borderRadius="md">
                    <RenderErrorBoundary>
                        <BackendProvider>
                            <SettingsProvider>
                                <AuthProvider>
                                    <BrowserRouter>
                                        <Routes>
                                            <Route element={<Shell />}>
                                                <Route index element={<HomePage />} />
                                                <Route path="*" element={<ErrorPage />}/>
                                                <Route path="/profile/:uid" element={<ProfilePageWrapper />} />
                                                <Route path="/user/:uid" element={<Redirect to="/profile/:uid" />} />
                                                <Route path="settings" element={<SettingsPage />}/>
                                                <Route path="builds" element={<BuildsPage />} />
                                                <Route path="leaderboards" element={<LeaderboardsPage />} />
                                                <Route path="leaderboards/:id" element={<LeaderboardDetailPage />} />
                                                <Route path="leaderboards/assault" element={<AssaultLeaderboardsPage />} />
                                                <Route path="leaderboards/assault/:id" element={<AssaultLeaderboardsDetailsPage />} />


                                                <Route path="kitchen" element={<KitchenSinkPage />} />

                                                <Route path="privacy" element={<PrivacyPage />} />

                                                <Route path="/auth/discord/callback" element={<AuthCallback.Discord />} />
                                            </Route>
                                        </Routes>
                                    </BrowserRouter>
                                </AuthProvider>
                            </SettingsProvider>
                        </BackendProvider>
                    </RenderErrorBoundary>
                </ContextMenuProvider>
        </MantineProvider>
    )
}
